// Brand marks for the Finances screen: banks, cards, bills, and car makes,
// from simple-icons (simpleicons.org, CC0), generated from its package and
// kept here so no logo is fetched from anywhere (which bank you use stays
// on this machine). Banks simple-icons has no mark for (Fidelity, Schwab,
// Capital One: their logos are trademarks it leaves out) stand as their
// initials on their colour, a mark of our own, never a copy of theirs. Some brands set rules for their mark; it stands only
// beside the account or payment it names. The colours are the brands own:
// data, not the app theme (app/preview/lint.mjs lists this file).

export interface Brand {
  /** The brand as people say it. */
  name: string;
  /** Its colour, and the ink that reads on it. */
  bg: string;
  ink: string;
  /** Its mark, a 24 by 24 path; or, for a monogram, its initials. */
  path?: string;
  letters?: string;
  /** What it is mostly: a bank, a card, a car make; empty for a bill. */
  kind: string;
}

